class Invoice {
  constructor(public type: string, public amount: number) {}
  calculateTax() {
    if (this.type === 'standard') return this.amount * 0.2;
    if (this.type === 'reduced') return this.amount * 0.1;
    return 0;
  }
}

class ShippingCalculator {
  calculate(order: { shippingType: string, weight: number }) {
    switch (order.shippingType) {
      case 'standard': return 5 + order.weight * 0.5;
      case 'express': return 15 + order.weight * 1.0;
      default: return 0;
    }
  }
}

// Version A
class Order {
  constructor(public type: string, public amount: number) {}
}
class OrderProcessor {
  calculateFee(order: Order) {
    if (order.type === 'standard') return order.amount * 0.05;
    if (order.type === 'express') return order.amount * 0.1;
    return 0;
  }
}
// Version B
abstract class BaseOrder {
  constructor(public amount: number) {}
  abstract calculateFee(): number;
}
class StandardOrder extends BaseOrder { calculateFee() { return this.amount * 0.05; } }
class ExpressOrder extends BaseOrder { calculateFee() { return this.amount * 0.1; } }
